field.eval:
[
  {'type': 'start', 'config': {'variables': []}},
  {'type': 'search', 'resultVariable': 'bills', 'config': {'args': {
    'model': 'account.move',
    'domain': [['move_type', '=', 'in_invoice'], ['payment_state', 'in', ['not_paid', 'partial']]],
    'fields': ['name', 'partner_id', 'amount_residual', 'invoice_date_due'],
    'limit': 15, 'order': 'invoice_date_due asc'}}},
  {'type': 'agent', 'resultVariable': 'plan', 'config': {'instruction': 'Draft a payment plan for the unpaid vendor bills in ${bills}: which to pay first, the total per vendor, and anything due this week.'}},
  {'type': 'output', 'config': {'value': '${plan}'}}
]

[
  {'type': 'start', 'config': {'variables': []}},
  {'type': 'search', 'resultVariable': 'products', 'config': {'args': {
    'model': 'product.template',
    'domain': [['list_price', '=', 0]],
    'fields': ['name', 'type', 'categ_id', 'default_code'],
    'limit': 20}}},
  {'type': 'agent', 'resultVariable': 'review', 'config': {'instruction': 'Review these zero-priced products in ${products}: which look like data entry mistakes (missing price) and which look intentional (free services)? List both groups.'}},
  {'type': 'output', 'config': {'value': '${review}'}}
]

[
  {'type': 'start', 'config': {'variables': [{'name': 'days', 'type': 'optional', 'value': 30, 'description': 'Drafts older than this many days'}]}},
  {'type': 'search', 'resultVariable': 'drafts', 'config': {'args': {
    'model': 'sale.order',
    'domain': [['state', '=', 'draft']],
    'fields': ['name', 'partner_id', 'amount_total', 'date_order'],
    'limit': 20, 'order': 'date_order asc'}}},
  {'type': 'agent', 'resultVariable': 'triage', 'config': {'instruction': 'Triage these stale draft quotations in ${drafts}: customer, amount, age. For each, say chase, revise, or cancel.'}},
  {'type': 'output', 'config': {'value': '${triage}'}}
]

[
  {'type': 'start', 'config': {'variables': [{'name': 'limit', 'type': 'optional', 'value': 10, 'description': 'How many recent customers to list'}]}},
  {'type': 'search', 'resultVariable': 'partners', 'config': {'args': {
    'model': 'res.partner',
    'domain': [['customer_rank', '>', 0]],
    'fields': ['name', 'email', 'phone', 'create_date'],
    'limit': 10, 'order': 'create_date desc'}}},
  {'type': 'agent', 'resultVariable': 'welcome', 'config': {'instruction': 'Write a one-paragraph welcome note idea for each new customer in ${partners}: what they bought or who they are, and one personal touch.'}},
  {'type': 'output', 'config': {'value': '${welcome}'}}
]

[
  {'type': 'start', 'config': {'variables': [{'name': 'minimum', 'type': 'optional', 'value': 1000, 'description': 'Only invoices with at least this residual'}]}},
  {'type': 'search', 'resultVariable': 'invoices', 'config': {'args': {
    'model': 'account.move',
    'domain': [['move_type', '=', 'out_invoice'], ['payment_state', 'in', ['not_paid', 'partial']]],
    'fields': ['name', 'partner_id', 'amount_residual', 'invoice_date_due'],
    'limit': 15, 'order': 'amount_residual desc'}}},
  {'type': 'agent', 'resultVariable': 'priority', 'config': {'instruction': 'Rank these open invoices in ${invoices} for collection priority: biggest residual and oldest due first, with the next action per invoice.'}},
  {'type': 'output', 'config': {'value': '${priority}'}}
]

[
  {'type': 'start', 'config': {'variables': []}},
  {'type': 'search', 'resultVariable': 'quants', 'config': {'args': {
    'model': 'stock.quant',
    'domain': [['quantity', '<=', 1], ['location_id.usage', '=', 'internal']],
    'fields': ['product_id', 'location_id', 'quantity', 'reserved_quantity'],
    'limit': 25}}},
  {'type': 'agent', 'resultVariable': 'report', 'config': {'instruction': 'Report the low stock in ${quants}: product, location, on hand vs reserved, and what to reorder first.'}},
  {'type': 'output', 'config': {'value': '${report}'}}
]

[
  {'type': 'start', 'config': {'variables': [{'name': 'customer', 'type': 'required', 'description': 'Customer name (or part of it)'}]}},
  {'type': 'search', 'resultVariable': 'partners', 'config': {'args': {
    'model': 'res.partner',
    'domain': [['name', 'ilike', '${customer}']],
    'fields': ['name', 'email', 'phone'],
    'limit': 3}}},
  {'type': 'agent', 'resultVariable': 'statement', 'config': {'instruction': 'For the customer matching ${partners}, find every unpaid invoice (out_invoice, not_paid or partial), total the residual, and age the debts. If several partners matched, say so and stop.'}},
  {'type': 'output', 'config': {'value': '${statement}'}}
]

[
  {'type': 'start', 'config': {'variables': [{'name': 'term', 'type': 'required', 'description': 'Product name fragment to look up'}]}},
  {'type': 'search', 'resultVariable': 'products', 'config': {'args': {
    'model': 'product.template',
    'domain': [['name', 'ilike', '${term}']],
    'fields': ['name', 'list_price', 'uom_id', 'categ_id'],
    'limit': 15}}},
  {'type': 'agent', 'resultVariable': 'pricelist', 'config': {'instruction': 'Turn these products in ${products} into a clean price list: name, price with currency, unit. Flag any with no price.'}},
  {'type': 'output', 'config': {'value': '${pricelist}'}}
]
